<script setup>
import { computed,ref } from 'vue';
import { daysBetween,fdate,ftime,money } from '../../lib/client-info';
import ClientPhone from './ClientPhone.vue';
import ClientOverview from './ClientOverview.vue';
import ClientBilling from './ClientBilling.vue';
import ClientPlans from './ClientPlans.vue';
import ClientSessions from './ClientSessions.vue';
import ClientAppointments from './ClientAppointments.vue';
import ClientFollowups from './ClientFollowups.vue';
import ClientMedical from './ClientMedical.vue';
const props=defineProps({bundle:Object,metrics:Object,tab:String,photo:String,payments:Array,paymentLoading:Boolean,paymentError:String});
const emit=defineEmits(['tab','close','retry-payments']);
const tabs=[['overview','👤','Overview'],['billing','🧾','Billing & dues'],['plans','📋','Plans'],['sessions','💆','Sessions'],['appointments','📅','Appointments'],['followups','📞','Followups'],['medical','🩺','Medical']];
const name=computed(()=>String(props.bundle.patient.patient_name||props.bundle.pid).toLocaleLowerCase().replace(/(^|[\s-])\p{L}/gu,value=>value.toLocaleUpperCase()));
const age=computed(()=>props.bundle.patient.dob?Math.floor(daysBetween(props.bundle.patient.dob,props.metrics.t)/365.25):'-');
const sex=computed(()=>/^female$/i.test(props.bundle.patient.sex)?'F':/^male$/i.test(props.bundle.patient.sex)?'M':'-');
const locked=computed(()=>Number(props.bundle.patient.disabled)===1||/locked/i.test(props.bundle.patient.status||''));
const closed=computed(()=>/closed|completed/i.test(props.bundle.patient.status||'')||props.metrics.status==='completed');
const photoOpen=ref(false);
const kpis=computed(()=>[['💰 '+(props.metrics.due.pending>0?'Due amount':'No dues'),money(props.metrics.due.pending),props.metrics.due.overdue?'⏰ '+money(props.metrics.due.overdueAmt)+' overdue':props.metrics.due.next?'Next due '+fdate(props.metrics.due.next):'Nothing pending'],['🧾 Invoices',props.metrics.invCount,props.metrics.due.withDues?props.metrics.due.withDues+' with balance':'All settled'],['💳 Lifetime paid',money(props.metrics.paid),props.metrics.nextTier?money(props.metrics.nextTier.min-props.metrics.paid)+' to '+props.metrics.nextTier.key:'Top tier'],['💆 Visits',props.metrics.visits,props.metrics.avgMonthly.toFixed(1)+' / month avg'],['📦 Package completion',props.metrics.completion+'%',props.metrics.doneS+' / '+props.metrics.totalS+' sessions'],['📅 Next visit',props.metrics.nextAppt?fdate(props.metrics.nextAppt.appointment_date):'—',props.metrics.nextAppt?ftime(props.metrics.nextAppt.appointment_time):props.metrics.last?'Last '+fdate(props.metrics.last):'No visits yet']]);
</script>
<template><div @keydown="event=>{if(event.key==='Escape'&&photoOpen){photoOpen=false;event.stopPropagation();}}"><div class="c3-hero" id="c3Hero"><div class="c3-profile-titlebar"><div class="c3-brandline c3-profile-title">Client Info - 360</div><button type="button" id="c3ModalClose" class="c3-close" aria-label="Close" @click="emit('close')">✕</button></div><div class="c3-hero-main"><div class="c3-avatar"><div class="c3-avatar-in"><img v-if="photo" :src="photo" alt="Client profile" @click="photoOpen=true"><span v-else class="c3-profile-placeholder" aria-hidden="true">👤</span></div><details v-if="photo" class="c3-photo-options"><summary title="Photo options" aria-label="Photo options">⋯</summary><div class="c3-photo-menu"><button type="button" @click="photoOpen=true">View photo</button></div></details></div><div class="c3-hero-id"><h2>{{ name }} <span class="c3-person-demographic">({{ sex }}/{{ age }})</span><span v-if="metrics.tier" class="c3-pill c3-tier" :class="'tone-'+metrics.tier.tone">{{ metrics.tier.icon }} {{ metrics.tier.key }}</span></h2><div class="c3-hero-meta"><ClientPhone v-if="metrics.phones.length" :value="metrics.phones[0].number" /><span class="c3-chip">Jn Dt: <b>{{ fdate(metrics.joined) }}</b></span><span class="c3-chip">BY <b>{{ metrics.joinedBy }}</b></span><span class="c3-chip">🏢 {{ metrics.home }}</span></div></div><div class="c3-hero-actions"><div class="c3-profile-status-grid"><div><small title="Client Status">St:</small><b :class="locked?'tone-neg':'tone-ok'">{{ locked?'Locked':closed?'Closed':'Active' }}</b></div><div><small title="Regularity">Reg:</small><b :class="metrics.consistency==='Regular'?'tone-ok':'tone-warn'">{{ metrics.consistency==='Regular'?'Reg':'Irreg' }}</b></div><div><small title="Medical Status">Med:</small><b :class="metrics.med.isMedical?'tone-neg':'tone-ok'">{{ metrics.med.isMedical?'Medical':'Non Medi' }}</b></div></div><a class="c3-btn c3-btn-light" :href="'/life_portal/appt?patient='+encodeURIComponent(bundle.pid)" target="_blank" rel="noopener">📅 Book appointment</a><button type="button" class="c3-btn c3-btn-light" @click="emit('tab','sessions')">💆 Sessions</button></div></div><div class="c3-hero-kpis"><div v-for="(row,index) in kpis" :key="row[0]" class="c3-hk" :class="{'c3-hk-due':index===0,'tone-neg':index===0&&metrics.due.overdue,'tone-warn':index===0&&metrics.due.pending&&!metrics.due.overdue}"><small>{{ row[0] }}</small><b :class="{'tone-ok':index===2,'c3-hk-sm':index===5}">{{ row[1] }}</b><span v-if="index===4" class="c3-meter"><i :style="{width:metrics.completion+'%'}"></i></span><em>{{ row[2] }}</em></div></div></div><nav class="c3-tabs" id="c3Tabs" role="tablist"><button v-for="[id,icon,label] in tabs" :key="id" role="tab" :data-tab="id" type="button" class="c3-tab" :class="{'is-on':tab===id}" :aria-selected="tab===id" @click="emit('tab',id)">{{ icon }} {{ label }}</button></nav><div class="c3-mbody" id="c3MBody"><ClientOverview v-if="tab==='overview'" :bundle="bundle" :metrics="metrics" /><ClientBilling v-else-if="tab==='billing'" :bundle="bundle" :metrics="metrics" :payments="payments" :busy="paymentLoading" :error="paymentError" @retry="emit('retry-payments')" /><ClientPlans v-else-if="tab==='plans'" :bundle="bundle" :metrics="metrics" /><ClientSessions v-else-if="tab==='sessions'" :bundle="bundle" :metrics="metrics" /><ClientAppointments v-else-if="tab==='appointments'" :bundle="bundle" :metrics="metrics" /><ClientFollowups v-else-if="tab==='followups'" :bundle="bundle" :metrics="metrics" /><ClientMedical v-else-if="tab==='medical'" :bundle="bundle" :metrics="metrics" /></div><div v-if="photoOpen" class="client-photo-preview" role="dialog" aria-modal="true" aria-label="Client photo" @click.self="photoOpen=false"><button type="button" aria-label="Close photo" @click="photoOpen=false">✕</button><img :src="photo" :alt="name"></div></div></template>
